[['▤','Rata-rata Nilai',avg===null?'—':avg,'Dari '+scores.length+' penilaian'],['✓','Ujian Selesai',exams.filter(e=>e.submitted_at).length||scores.length,'Dari '+exams.length+' ujian tercatat'],['♟','Kehadiran',pct===null?'—':pct+'%',hadir+' dari '+attendance.length+' pertemuan'],['▣','Materi Dipelajari',materials.length,'Materi tercatat']].forEach(([icon,label,value,sub])=>{const card=el('div','pr-stat');card.append(el('span','pr-stat-icon',icon));const txt=el('div');txt.append(el('small','',label),el('strong','',value),el('span','',sub));card.append(txt);summary.append(card);});root.append(summary);
